已知带头结点的循环链表 heada 中存放一组整型数，数据类型定义如下：
typedef struct LNode {
  int data;
  LNode *next;
} LNode;
请设计算法：将链表 heada 中值为奇数的结点加入链表 headb 中，且链表 headb 按值非递增排列。函数原型为 void Splithb(LNode *heada, LNode *&headb)。

answer.referenceAnswer:
void Inserthb(LNode *heada,LNode *&headb){
  headb=new LNode;
  headb->next=headb;
  LNode *pa=heada->next,*prb,*pb,*s;
  while(pa!=heada){
    if(pa->data%2==1){
      prb=headb;pb=headb->next;
      while(pb!=headb&&pa->data<pb->data){prb=pb;pb=pb->next;}
      s=new LNode;
      s->data=pa->data;
      s->next=pb;prb->next=s;
    }
    pa=pa->next;
  }
}

