已知有向图采用邻接矩阵存储，类型定义如下：
typedef struct {
  int vexnum, arcnum;
  char vexs[MAX];
  int arcs[MAX][MAX];
} MGraph;
将图中出度大于入度的顶点称为 K 顶点。请设计算法：对给定的任意非空有向图 G，输出 G 中所有的 K 顶点，并返回 K 顶点的个数，函数原型为 int count(MGraph mg)。

answer.referenceAnswer:
int count(MGraph mg){
  int count1,count2,count=0,i,j;
  for(i=0;i<mg.vexnum;i++){
    count1=count2=0;
    for(j=0;j<mg.vexnum;j++){
      if(mg.arcs[i][j]) count1++;
      if(mg.arcs[j][i]) count2++;
    }
    if(count1>count2){
      count++;
      cout<<mg.vexs[i]<<' ';
    }
  }
  return count;
}
